def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 100:
        return 'D'

    me = [h[0] for h in history]
    opp = [h[1] for h in history]

    c_opp = sum(1 for x in opp if x == 'C')
    d_opp = n - c_opp

    if c_opp == 0:
        return 'D'

    last_opp = opp[-1]
    last_me = me[-1]

    if n == 99:
        return 'D'

    K = 10

    if d_opp == 0:
        if n < K:
            return 'C'

        confirm = False
        for i in range(1, n):
            if (me[i - 1] == 'D' and opp[i - 1] == 'C' and
                me[i] == 'C' and opp[i] == 'C'):
                confirm = True
                break

        if confirm:
            return 'D'
        if last_me == 'C':
            return 'D'
        return 'C'

    if d_opp * 100 >= n * 65:
        return 'D'

    streak_d = 0
    i = n - 1
    while i >= 0 and opp[i] == 'D':
        streak_d += 1
        i -= 1

    if last_opp == 'D' and streak_d >= 3:
        return 'D'

    po = 0
    pc = 0
    uo = 0
    uc = 0
    mirror = 0

    for i in range(1, n):
        if opp[i] == me[i - 1]:
            mirror += 1

        if me[i - 1] == 'D':
            po += 1
            if opp[i] == 'D':
                pc += 1
        else:
            uo += 1
            if opp[i] == 'D':
                uc += 1

    punish_rate = pc / po if po else 0.0
    unprov_rate = uc / uo if uo else 0.0
    mirror_rate = mirror / (n - 1) if n > 1 else 0.0
    opp_def_rate = d_opp / n

    if unprov_rate > 0.45:
        return 'D'

    rec_d = sum(1 for x in opp[-10:] if x == 'D')

    reactive = (
        mirror_rate > 0.62 or
        (pc >= 1 and punish_rate >= 0.35 and unprov_rate < 0.35 and c_opp > d_opp)
    )

    forgiving = (
        po >= 2 and
        punish_rate < 0.30 and
        unprov_rate < 0.30 and
        c_opp > d_opp * 2
    )

    remaining = 100 - n

    if remaining <= 5:
        if forgiving:
            return 'D'

        if reactive:
            if c_opp * 100 >= n * 65:
                if remaining == 2:
                    return 'C'
                return 'C'

        if c_opp * 100 >= n * 70 and rec_d <= 2:
            return 'D'

        if last_opp == 'C':
            return 'D'

        if c_opp * 100 >= n * 60:
            return 'C'

        return 'D'

    if reactive:
        if rec_d >= 4:
            return 'D'
        return 'C'

    if forgiving:
        if last_opp == 'C':
            return 'D'
        if c_opp * 100 >= n * 80:
            return 'C'
        return 'D'

    if opp_def_rate >= 0.45:
        return 'D'

    if n >= 6:
        alt = 0
        for i in range(1, n):
            if opp[i] != opp[i - 1]:
                alt += 1
        if alt >= n - 2:
            return 'D'

    if last_opp == 'D':
        if c_opp * 100 >= n * 85:
            return 'C'

        if c_opp * 100 >= n * 70 and rec_d <= 1:
            return 'C'

        if rng.random() < 0.25:
            return 'C'

        return 'D'

    if c_opp * 100 >= n * 75:
        return 'C'

    if rng.random() < 0.05:
        return 'D'

    return 'C'
